// Ambient types so TypeScript understands the Cloudflare env injected by OpenNext.
// Generated by `npm run cf-typegen` after the first successful build.
interface Env {
  // Plain env vars (set via wrangler.jsonc `vars` or dashboard)
  NEXTAUTH_URL: string;
  WEBHOOK_URL: string;

  // Secrets (set via `wrangler secret put NAME` or dashboard)
  DATABASE_URL: string;
  NEXTAUTH_SECRET: string;
  GOOGLE_CLIENT_ID: string;
  GOOGLE_CLIENT_SECRET: string;
  STRIPE_SECRET_KEY: string;
  STRIPE_WEBHOOK_SECRET: string;
  NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY: string;
  MUAPIAPP_API_KEY: string;

  // OpenNext asset binding (declared in wrangler.jsonc)
  ASSETS: Fetcher;
}
